static const char WifiSetupPageStart[]=R"HTML(<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>iPhone Agent Harness — Wi-Fi</title><style>body{font:16px system-ui;max-width:30rem;margin:2rem auto;padding:1rem}input,button{font:inherit;padding:.8rem;box-sizing:border-box;width:100%;margin:.5rem 0}pre{white-space:pre-wrap;overflow-wrap:anywhere}</style><h1>Connect to Wi-Fi</h1><form id="f"><label><span id="ssid-label">Wi-Fi name</span><input name="ssid" required maxlength="32" autocomplete="off"></label><label><span id="password-label">Wi-Fi password</span><input name="password" type="password" maxlength="63" autocomplete="off"></label><button>Connect</button></form><p id="out"></p><a id="back" hidden>Return to Harness</a><script>const owner=)HTML";
static const char WifiSetupPageEnd[]=R"HTML(;const f=document.querySelector('#f'),out=document.querySelector('#out'),back=document.querySelector('#back');/*iah-localization-start*/const pageMessages={"en":["Connect to Wi-Fi","Wi-Fi name","Wi-Fi password","Connect","Connecting…","Switch back to your home Wi-Fi, then return to Harness.","Could not connect. Check the Wi-Fi details and try again."],"zh-Hans":["连接 Wi-Fi","Wi-Fi 名称","Wi-Fi 密码","连接","正在连接…","请切回家里的 Wi-Fi，然后返回 Harness。","连接失败，请检查 Wi-Fi 名称和密码后重试。"],"zh-Hant":["連接 Wi-Fi","Wi-Fi 名稱","Wi-Fi 密碼","連接","正在連接…","請切回家中的 Wi-Fi，然後返回 Harness。","連接失敗，請檢查 Wi-Fi 名稱和密碼後再試。"],"ja":["Wi-Fi に接続","Wi-Fi 名","Wi-Fi パスワード","接続","接続中…","自宅の Wi-Fi に戻り、Harness を開いてください。","接続できません。Wi-Fi 名とパスワードを確認してください。"],"ru":["Подключение к Wi-Fi","Имя сети Wi-Fi","Пароль Wi-Fi","Подключить","Подключение…","Вернитесь в домашнюю сеть Wi-Fi и откройте Harness.","Нет подключения. Проверьте имя сети и пароль."],"de":["Mit WLAN verbinden","WLAN-Name","WLAN-Passwort","Verbinden","Verbindung wird hergestellt…","Wechsle zurück in dein WLAN und öffne Harness.","Keine Verbindung. Prüfe WLAN-Name und Passwort."],"fr":["Se connecter au Wi-Fi","Nom du réseau Wi-Fi","Mot de passe Wi-Fi","Connecter","Connexion…","Revenez à votre Wi-Fi habituel, puis à Harness.","Connexion impossible. Vérifiez le nom du réseau et le mot de passe."],"es":["Conectar a Wi-Fi","Nombre de Wi-Fi","Contraseña de Wi-Fi","Conectar","Conectando…","Vuelve a tu Wi-Fi habitual y abre Harness.","No se pudo conectar. Comprueba el nombre de red y la contraseña."]};function choosePageLanguage(messages,forced){for(const raw of [forced,...(navigator.languages||[]),navigator.language]){if(typeof raw!=='string')continue;const tag=raw.toLowerCase().replaceAll('_','-');const code=tag.startsWith('zh')?(/hant|-(tw|hk|mo)(-|$)/.test(tag)?'zh-Hant':'zh-Hans'):tag.split('-')[0];if(Object.hasOwn(messages,code))return code;}return 'en';}/*iah-localization-end*/const language=choosePageLanguage(pageMessages,new URLSearchParams(location.search).get('lang')),copy=pageMessages[language];document.documentElement.lang=language;document.title='iPhone Agent Harness · '+copy[0];document.querySelector('h1').textContent=copy[0];document.querySelector('#ssid-label').textContent=copy[1];document.querySelector('#password-label').textContent=copy[2];f.querySelector('button').textContent=copy[3];back.textContent={"en":"Return to Harness","zh-Hans":"返回 Harness","zh-Hant":"返回 Harness","ja":"Harness に戻る","ru":"Вернуться в Harness","de":"Zurück zu Harness","fr":"Retour à Harness","es":"Volver a Harness"}[language];const setupFetch=async(path,options={})=>{const abort=new AbortController(),timer=setTimeout(()=>abort.abort(),4000);try{return await fetch(path,{...options,signal:abort.signal,cache:'no-store'});}finally{clearTimeout(timer);}};
f.onsubmit=async e=>{e.preventDefault();f.querySelector('button').disabled=true;back.hidden=true;out.textContent=copy[4];try{
 const v=Object.fromEntries(new FormData(f));v.setupPassword=owner;v.origin='https://igent.cc';v.unixTime=Math.floor(Date.now()/1000);
 const r=await setupFetch('/configure',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(v)});const result=await r.json();if(!r.ok||result.accepted!==true)throw Error('configuration rejected');
 let connected=null;const until=Date.now()+32000;
 while(Date.now()<until){await new Promise(resolve=>setTimeout(resolve,800));let status;try{const response=await setupFetch('/connection-status');if(!response.ok)continue;status=await response.json();}catch{continue;}if(status.status==='failed')throw Error('connection failed');if(status.status==='connected'&&status.configured===true){connected=status;break;}}
 if(!connected)throw Error('connection timeout');
 const done=await setupFetch('/finish',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({setupPassword:owner})});if(!done.ok)throw Error('connection not ready');
 const code={v:1,url:connected.httpUrl,id:connected.boardId,pairingCodeRequired:false,...(connected.rtc?{rtc:connected.rtc}:{})};const encoded=btoa(JSON.stringify(code)).replaceAll('+','-').replaceAll('/','_').replace(/=+$/,'');const site=new URL(connected.harnessURL||'https://igent.cc/');if(site.protocol!=='https:')throw Error(copy[6]);site.hash='device='+encoded;back.href=site.href;back.hidden=false;out.textContent=copy[5];
 }catch(e){out.textContent=copy[6];f.querySelector('button').disabled=false}};
</script>)HTML";
